import React, { createContext, Dispatch, SetStateAction } from 'react';

export type ActionItemsContextProps = {
  /** Whether the ActionItems slot is used in the AppHeader. */
  hasActions: boolean;
  /** Whether the ActionItems are collapsed. */
  isActionItemsCollapsed: boolean;
  /** Function to update the isActionItemsCollapsed context value. */
  setIsActionItemsCollapsed: Dispatch<SetStateAction<boolean>>;
};

/**
 * ActionItems context, used to access the collapsed/expanded state of the items in other components.
 */
export const ActionItemsContext: React.Context<ActionItemsContextProps> =
  createContext<ActionItemsContextProps>({
    hasActions: false,
    isActionItemsCollapsed: false,
    setIsActionItemsCollapsed: () => false,
  });
